const withdrawShare = `-- name: WithdrawShare :execrows
UPDATE shares SET withdrawn_at = ? WHERE id = ? AND user_id = ? AND withdrawn_at IS NULL
`

type WithdrawShareParams struct {
	WithdrawnAt *int64
	ID          string
	UserID      string
}

func (q *Queries) WithdrawShare(ctx context.Context, arg WithdrawShareParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, withdrawShare, arg.WithdrawnAt, arg.ID, arg.UserID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
